Throughout, we assume that $p$ is a fixed constant, and thus do not include constants depending on $p$ (e.g. $p$, $2^p$) in our big-O notation. We do include precise constants involving $p$ that appear in the exponents of other terms like $d$ and $1/\epsilon$. For simplicity, we also assume that our design matrix $\bfA\in \R^{n\times d}$ is overdetermined ($n > d$) and has full-rank (i.e., rank $d$). This is without loss of generality, as if $\bfA$ had rank $r < d$ we could replace it with an $n \times r$ basis for its column span and solve the regression problem with that basis as the design matrix. 

We denote the maximum of two real numbers $a,b$ by $a\lor b$ and the minimum as $a\land b$. We access the coordinates of vectors as $\bfv_i$ or $\bfv(i)$, which means the $i$th coordinate of $\bfv\in\mathbb R^n$.

\begin{definition}[$\ell_p$ sensitivity]
For any $\bfA \in \R^{n \times d}$ and $0 < p < \infty$ define the $\ell_p$ sensitivity of row $i$ for $i\in[n]$ as:
\begin{align*}
\bfs^p_i(\bfA) \coloneqq \max_{\bfx \in \R^d\setminus\{0\}} \frac{|[\bfA\bfx](i)|^p}{\norm{\bfA\bfx}_p^p}.
\end{align*}
\end{definition}

\begin{definition}[$\ell_p$ Lewis weight \cite{CohenPeng:2015}]\label{def:lewis}
For any $\bfA \in \R^{n \times d}$ and $0<p<\infty$ the $\ell_p$ Lewis weights $\{\bfw^p_1(\bfA), \ldots, \bfw^p_n(\bfA) \}$ are the unique set of weights such that, if we let $\bfW \in \R^{n \times n}$ be the diagonal matrix with $\bfW(i,i) = \bfw_i^p(\bfA)$, then for all $i$,
\begin{align*}
 \bfw_i^p(\bfA) = \bfs^2_i (\bfW^{1/2-1/p} \bfA).
\end{align*}
Here $\bfs^2_i (\bfW^{1/2-1/p} \bfA)$ is the $i^\text{th}$ leverage score of $\bfW^{1/2-1/p} \bfA$. Note that the leverage scores of a full-rank matrix always sum to $d$, so we have $\sum_{i=1}^n \bfw^p_i(\bfA) = d$. 
\end{definition}

\begin{theorem}[\cite{CohenLeeMusco:2015, CohenPeng:2015}]\label{thm:cohen-peng-fast-lewis-weights}
	Let $\bfA\in\mathbb R^{n\times d}$. There is an algorithm which computes upper bounds $\tilde\bfw_i^p(\bfA) \geq \bfw_i^p(\bfA)$ to the $\ell_p$ Lewis weights of $\bfA$ such that
	\[
		\sum_{i=1}^n \tilde\bfw_i^p(\bfA) = O(d)
	\]
	with the following running times:
	\begin{itemize}
	\item for $p = 2$: $O(\nnz(\bfA) + d^\omega\log^2 d)$
	\item for $0 < p < 4$: $O(\nnz(\bfA)\log n + d^{\omega})$
	\item for $p \geq 2$: $O(\nnz(\bfA)\log n + d^{p/2 + O(1)})$
	\end{itemize}
	Here, $\omega \approx 2.37286$ is the current exponent of fast matrix multiplication. 
	\end{theorem}

\begin{definition}\label{dfn:polynomially-bounded}
Let $M:\mathbb R_{\geq0}\to\mathbb R_{\geq0}$ be increasing. If there exist constants $p>0$ and $c_U\geq 1$ such that for all $y>x$, 
\[
    \frac{M(y)}{M(x)} \leq c_U \parens*{\frac{y}{x}}^p,
\]
then we say that $M$ is \emph{polynomially bounded above with degree $p$ and constant $c_U$}. Similarly, if there exists constants $q>0$ and $c_L\geq 1$ such that for all $y>x$,
\[
    \frac{M(y)}{M(x)} \geq c_L \parens*{\frac{y}{x}}^q,
\]
then we say that $M$ is \emph{polynomially bounded below with degree $q$ and constant $c_L$}.
\end{definition}

\begin{definition}[$M$-norm]\label{dfn:m-norm}
Let $M:\mathbb R_{\geq0}\to\mathbb R_{\geq0}$ be such that
\begin{itemize}
    \item $M(0) = 0$
    \item $M$ is nondecreasing
    \item $M$ is polynomially bounded above with degree $p_M$ and constant $c_U$ (see Definition \ref{dfn:polynomially-bounded})
\end{itemize}
Let $\bfw\in\mathbb R^n$ be a set of weights such that
\[
    \bfw_i \geq 1
\]
for all $i\in[n]$. Then, we define the $M$-norm of a vector $\bfx\in\mathbb R^n$ as
\[
    \norm*{\bfx}_{M,\bfw} \coloneqq \bracks*{\sum_{i=1}^n \bfw_i M(\abs*{\bfx_i})}^{1/p_M}.
\]
If $\bfw$ is the vector of all ones, we simple write $\norm*{\bfx}_{M}$ for $\norm*{\bfx}_{M,\bfw}$. If $M(x) = \abs*{x}^p$ for some $p>0$, then we write $\norm*{\bfx}_{p,\bfw}$ for $\norm*{\bfx}_{M,\bfw}$.
\end{definition}

\begin{definition}[$M$ balls and spheres]\label{dfn:m-ball-sphere}
    Let $\bfA\in\mathbb R^{n\times d}$ and let $\mathcal V = \Span(\bfA)$. Let $M:\mathbb R_{\geq0}\to\mathbb R_{\geq0}$ satisfy the conditions of Definition \ref{dfn:m-norm}, and let $\bfw\geq\mathbf{1}_n$ be a set of weights. Define the ball $\mathcal B^{M,\bfw}_\rho$ of radius $\rho>0$ as
    \[
        \mathcal B^{M,\bfw}_\rho \coloneqq \braces*{\bfy \in \mathcal V: \norm*{\bfy}_{M,\bfw} \leq \rho}.
    \]
    Similarly define the sphere $\mathcal S^{M,\bfw}_\rho$ of radius $\rho>0$ as
    \[
        \mathcal S^{M,\bfw}_\rho \coloneqq \braces*{\bfy \in \mathcal V: \norm*{\bfy}_{M,\bfw} = \rho}.
    \]
    If $\bfw = \mathbf{1}_n$, then we simply write $\mathcal B_\rho^{M}$ and $\mathcal S_\rho^{M}$, respectively.
    \end{definition}

\begin{definition}[$M$-sensitivity]\label{dfn:m-sensitivity}
Let $\bfA\in\mathbb R^{n\times d}$ and let $\norm*{\cdot}_M$ be an $M$-norm. Then, the \emph{$i$th $M$-sensitivity} is defined as
\[
    \bfs_i^M(\bfA) \coloneqq \sup_{\bfx\in\mathbb R^d, \bfA\bfx\neq 0} \frac{M(\abs*{[\bfA\bfx](i)})}{\norm*{\bfA\bfx}_M^{p_M}}
\]
and the \emph{total $M$-sensitivity} is defined as
\[
    \mathcal T^M(\bfA)\coloneqq \sum_{i=1}^n \bfs_i^M(\bfA).
\]
Let $\bfw\geq\mathbf{1}_n$ be a set of weights. Then, the \emph{$i$th weighted $M$-sensitivity} is defined as
\[
    \bfs_i^{M,\bfw}(\bfA) \coloneqq \sup_{\bfx\in\mathbb R^d, \bfA\bfx\neq 0} \frac{\bfw_i M(\abs*{[\bfA\bfx](i)})}{\norm*{\bfA\bfx}_{M,\bfw}^{p_M}}
\]
and the \emph{total weighted $M$-sensitivity} is defined as
\[
    \mathcal T^{M,\bfw}(\bfA)\coloneqq \sum_{i=1}^n \bfs_i^{M,\bfw}(\bfA).
\]
\end{definition}

\begin{definition}[Sensitivity Sampling for $M$-Estimators]\label{def:m-sensitivity-sampling}
Let $\bfA\in\mathbb R^{n\times d}$, let $\norm*{\cdot}_M$ be an $M$-norm, and let $\bfw\geq\mathbf{1}_n$ be a set of weights. Let $m$ be an oversampling parameter. Then, a random set of weights $\bfw'$ is sampled according to sensitivity upper bounds $\tilde\bfs_i^{M,\bfw}(\bfA) \geq \bfs_i^{M,\bfw}(\bfA)$ (see Definition \ref{dfn:m-sensitivity}) if 
\[
    \bfw_i' \coloneqq \begin{cases}
        \bfw_i/\bfp_i & \text{w.p. $\bfp_i$} \\
        0 & \text{otherwise}
    \end{cases}
\]
where $\bfp_i \coloneqq \min\{1,m\cdot \tilde\bfs_i^{M,\bfw}(\bfA)\}$.
\end{definition}

\begin{algorithm}
	\caption{Sensitivity upper bounds}
	\textbf{input:} Matrix $\bfA \in \mathbb R^{n \times d}$, $M$-norm $M$, parameter $1\leq\tau\leq n$. \\
	\textbf{output:} Upper bounds $\tilde\bfs_i^M(\bfA)$ on $\bfs_i^M(\bfA)$. 
	\begin{algorithmic}[1] \State Initialize $\tilde\bfs_i^M(\bfA) \leftarrow 2\tau/n$.
        \For{$r\in[\ceil{\log_2(n/\tau)}]$}
            \For{$t\in[O(\log n)]$}
                \State Hash the rows of $\bfA$ into $B = 10\cdot 2^r$ buckets $S_1, S_2, \dots, S_B$. \label{line:hash-rows}
                \State Compute $O(1)$-approximate $\ell_p$ Lewis weights of each of the $B$ buckets $\bfA\mid_{S_1}, \bfA\mid_{S_2}, \dots, \bfA\mid_{S_B}$. \label{line:approx-lewis-weights}
                \State For any row $i$ with an $\ell_{p_M}$ Lewis weight of at least $\Omega(1)$, set $\tilde\bfs_i^M(\bfA) \leftarrow \max\{2/2^r, \tilde\bfs_i^M(\bfA)\}$. \label{line:assign-m-sensitivity}
            \EndFor
        \EndFor
	\end{algorithmic}\label{alg:m-estimator-alg-sensitivity}
\end{algorithm}

\begin{restatable}[Main Result for Sensitivity Bounds]{theorem}{SensitivityBound}\label{thm:m-estimator-alg}
Let $\norm*{\cdot}_M$ be an $M$-norm. Let $1\leq \tau\leq n$ be a parameter. Then, with probability at least $99/100$, Algorithm \ref{alg:m-estimator-alg-sensitivity} computes sensitivity upper bounds $\tilde\bfs_i^M(\bfA) \geq \bfs_i^M(\bfA)$ that sum to at most
\[
    \tilde{\mathcal T}^M(\bfA) \coloneqq \sum_{i=1}^n \tilde\bfs_i^M(\bfA) = O(d^{\max\{1,p_M/2\}} \log^2 n + \tau).
\]
If constant factor Lewis weight approximation takes for an $n\times d$ matrix $\bfB$ takes $O(\nnz(\bfB)\log n + T)$ time (see Theorem \ref{thm:cohen-peng-fast-lewis-weights}), then the total running time is
\[
    O\parens*{\nnz(\bfA)\log^3 n + \frac{nT}{\tau}\log n}.
\]
\end{restatable}

\begin{lemma}\label{lem:weighted-m-sensitivity-bound}
    Let $\norm*{\cdot}_M$ be an $M$-norm. Let $\bfw\geq\mathbf{1}_n$ be a set of weights. Let $N\coloneqq \ceil*{\log_2(1+\norm*{\bfw}_\infty)}$. For $j\in[N]$, let
\[
    T_j \coloneqq \braces*{i\in[n] : 2^{j-1}\leq \bfw_i < 2^j},
\]
and let $\bfA\mid_{T_j}$ denote the restriction of $\bfA$ to the rows of $T_j$. Then,
\[
    \bfs_i^{M,\bfw}(\bfA) \leq 2\cdot \bfs_i^M(\bfA\mid_{T_j})
\]
for $i\in T_j$. 
\end{lemma}

Throughout this section, we assume the following. Let $\bfA\in\mathbb R^{n\times d}$ and let $\mathcal V = \Span(\bfA)$. Let $M:\mathbb R_{\geq0}\to\mathbb R_{\geq0}$ satisfy the conditions of Definition \ref{dfn:m-norm}, and furthermore that
\begin{itemize}
    \item $M^{1/p_M}$ is subadditive
    \item $M$ is polynomially bounded below with degree $q_M$ and constant $c_L$ (see Definition \ref{dfn:polynomially-bounded})
\end{itemize}

In the linear regression problem with the $M$-loss, we are given a matrix $\bfA\in\mathbb R^{n\times d}$ and a vector $\bfb\in\mathbb R^n$ we must solve the following optimization problem:
\[
    \min_{\bfx\in\mathbb R^d}\norm*{\bfA\bfx - \bfb}_M.
\]
We will also consider the weighted version, i.e.
\begin{equation}\label{eqn:m-linear-regression}
    \min_{\bfx\in\mathbb R^d}\norm*{\bfA\bfx - \bfb}_{M,\bfw}
\end{equation}
for a set of weights $\bfw\geq\mathbf{1}_n$. Throughout this section, let for a given weighted $M$-norm $\norm*{\cdot}_{M,\bfw}$, let
\[
    \OPT \coloneqq \min_\bfx\norm*{\bfA\bfx-\bfb}_{M,\bfw}.
\]

\begin{lemma}[Constant Factor Approximation]\label{lem:m-sensitivity-constant-factor-approx}
    Let $\bfw\geq\mathbf{1}_n$ be a set of weights. Let $\bfw'\geq\mathbf{1}_n$ be a random set of weights that satisfies the following:
    \begin{itemize}
        \item $\E_{\bfw'}\norm*{\bfy}_{M,\bfw'} = \norm*{\bfy}_{M,\bfw}$ for any fixed $\bfy\in\mathbb R^n$
        \item $\bfw'$ is a $1/8$-subspace embedding for any $\mathcal S_\rho^M$ for any fixed $\rho>0$ with probability at least $9/10$, that is,
        \[
            \Pr\braces*{\norm*{\bfA\bfx}_{M,\bfw'} = \parens*{1\pm\frac18}\norm*{\bfA\bfx}_{M,\bfw}, \forall \bfA\bfx\in\mathcal S_\rho^M} \geq \frac{9}{10}
        \]
    \end{itemize}
    Let $\tilde\bfx$ satisfy
    \[
        \norm*{\bfA\tilde\bfx - \bfb}_{M,\bfw'} \leq \kappa\min_{\bfx\in\mathbb R^d}\norm*{\bfA\bfx - \bfb}_{M,\bfw'}.
    \]
    Then, with constant probability,
    \[
        \norm*{\bfA\tilde\bfx - \bfb}_{M,\bfw} \leq O(\kappa)\min_{\bfx\in\mathbb R^d} \norm*{\bfA\bfx - \bfb}_{M,\bfw}.
    \]
\end{lemma}

\begin{lemma}\label{lem:opt-norm-bound}
    Let $\bfA\in\mathbb R^{n\times d}$ and let $\bfb\in\R^n$. Let $\bfw\geq\mathbf{1}_n$ and let $\norm*{\cdot}_M$ be an $M$-norm that satisfies an approximate triangle inequality, that is,
    \[
        M^{1/p_M}(a+b) \leq O(1)(M^{1/p_M}(a) + M^{1/p_M}(b)).
    \]
    Suppose that $\bfx_c\in\R^d$ satisfies
    \[
        \norm*{\bfA\bfx_c - \bfb}_{M,\bfw} \leq O(1)\min_\bfx\norm*{\bfA\bfx - \bfb}_{M,\bfw} = O(\OPT)
    \]
    and let $\bfb' = \bfb - \bfA\bfx_c$. Let $\bar\bfx$ satisfy
    \[
        \norm*{\bfA\bar\bfx-\bfb'}_{M,\bfw} \leq O(1)\min_\bfx\norm*{\bfA\bfx-\bfb'}_{M,\bfw} = O(\OPT).
    \]
    Then, $\norm*{\bfA\bar\bfx}_{M,\bfw} = O(\OPT)$.
\end{lemma}

\begin{lemma}\label{lem:reduction-to-good-b-coordinates}
    Consider the setting of Lemma \ref{lem:opt-norm-bound}. Further suppose that either
    \begin{enumerate}[label={(\arabic*)}]
    \item for any $a,b\in\R$ with $M(a)\leq\eps^{p_M}M(b)$,
    \[
        M(a+b) = (1\pm O(\eps))M(b)
    \]
    \item $M^{1/p_M}$ is subadditive
    \end{enumerate}
    Let $\tilde\bfs_i^{M,\bfw}(\bfA) \geq \bfs_i^{M,\bfw}(\bfA)$ be upper bounds on the weighted $M$-sensitivities of $\bfA$. Let 
    \[
        \mathcal B \coloneqq \braces*{i\in[n] : \bfw_i M(\bfb_i') > \frac{\tilde\bfs_i^{M,\bfw}(\bfA)\OPT^{p_M}}{\eps^{p_M}}}
    \]
    Let $\bfw'$ be a set of random weights such that for any fixed $\bfy\in\R^n$, $\E_{\bfw'}\norm*{\bfy}_{M,\bfw'}^{p_M} = \norm*{\bfy}_{M,\bfw}^{p_M}$, and such that with probability at least $1-\delta$ satisfies
    \begin{equation}\label{eq:good-coordinates-guarantee}
        \norm*{(\bfA\bfx-\bfb')\mid_{\overline{\mathcal B}}}_{M,\bfw'}^{p_M} = \norm*{(\bfA\bfx-\bfb')\mid_{\overline{\mathcal B}}}_{M,\bfw}^{p_M} \pm O(\eps)\OPT^{p_M}
    \end{equation}
    for every $\bfA\bfx$ with $\norm*{\bfA\bfx}_{M,\bfw} = O(\OPT)$. Then with probability at least $1-\delta$, there is a $C$ with $\abs*{C} \leq O(\OPT^{p_M}/\delta)$ such that
    \begin{align*}
        \abs*{\norm*{\bfy - \bfb'}_{M,\bfw'}^{p_M} - \norm*{\bfy - \bfb'}_{M,\bfw'}^{p_M} - C} = O(\eps/\delta)\OPT^{p_M}.
    \end{align*}
\end{lemma}

\begin{lemma}\label{lem:m-bernstein-good-coordinates}
    Consider the setting of Lemma \ref{lem:reduction-to-good-b-coordinates}. Let $\bfA\bfx$ have $\norm*{\bfA\bfx}_{M,\bfw} = O(\OPT)$ and let $\bfy = \bfA\bfx- \bfb'$. Let $m\geq 1$ be a parameter and let $\bfw'$ be obtained from weights $\bfw$ according to Definition \ref{def:m-sensitivity-sampling}. Then,
    \[
        \Pr\braces*{\abs*{\norm*{(\bfA\bfx-\bfb')\mid_{\overline{\mathcal B}}}_{M,\bfw'}^{p_M} - \norm*{(\bfA\bfx-\bfb')\mid_{\overline{\mathcal B}}}_{M,\bfw}^{p_M}} \geq \eps\OPT^{p_M}} \leq \exp\parens*{-\Theta(1)m\eps^{2+p_M}}
    \]
\end{lemma}

\begin{algorithm}
	\caption{Input sparsity time, constant factor $M$-estimator active regression}
	\textbf{input:} Matrix $\bfA \in \R^{n \times d}$, measurement vector $\bfb\in\R^n$. \\
	\textbf{output:} Constant factor approximate solution $\bfx_c\in\R^d$ to $\min_\bfx\norm*{\bfA\bfx-\bfb}_M$.
	\begin{algorithmic}[1] \State Run Algorithm \ref{thm:m-estimator-alg} to obtain approximate sensitvities $\tilde\bfs_i^M(\bfA)$ with $\tau = T$\footnote{See Theorem \ref{thm:m-active-regression} for the definition of this setting.}
        \State Given weights $\mathbf{1}_n$, obtain $\bfw$ according to Definition \ref{def:m-sensitivity-sampling}
        \State Run Algorithm \ref{thm:m-estimator-alg} to obtain approximate sensitvities $\tilde\bfs_i^{M,\bfw}(\bfA)$ with $\tau = d$
        \State Given weights $\bfw$, obtain $\bfw'$ according to Definition \ref{def:m-sensitivity-sampling}
        \State Let $\bfx_c$ be an approximate solution $\norm*{\bfA\bfx_c-\bfb}_{M,\bfw'} \leq O(1)\min_\bfx\norm*{\bfA\bfx-\bfb}_{M,\bfw'}$
        \State \Return $\bfx_c$
	\end{algorithmic}\label{alg:constant-m-active-regression}
\end{algorithm}

\begin{algorithm}
	\caption{Input sparsity time, relative error $M$-estimator active regression}
	\textbf{input:} Matrix $\bfA \in \R^{n \times d}$, measurement vector $\bfb\in\R^n$. \\
	\textbf{output:} Approximate solution $\tilde\bfx\in\R^d$ to $\min_\bfx\norm*{\bfA\bfx-\bfb}_M$.
	\begin{algorithmic}[1] \State Run Algorithm \ref{alg:constant-m-active-regression} to obtain a constant factor solution $\bfx_c$
        \State Set $\bfb' \gets \bfb - \bfA\bfx_c$
        \State Run Algorithm \ref{thm:m-estimator-alg} to obtain approximate sensitvities $\tilde\bfs_i^M(\bfA)$ with $\tau = T$
        \State Given weights $\mathbf{1}_n$, obtain $\bfv$ according to Definition \ref{def:m-sensitivity-sampling}
        \State Run Algorithm \ref{thm:m-estimator-alg} to obtain approximate sensitvities $\tilde\bfs_i^{M,\bfv}(\bfA)$ with $\tau = d$
        \State Given weights $\bfv$, obtain $\bfv'$ according to Definition \ref{def:m-sensitivity-sampling}
        \State Let $\bar\bfx$ be an approximate solution $\norm*{\bfA\bar\bfx-\bfb}_{M,\bfv'} \leq (1+\eps)\min_\bfx\norm*{\bfA\bfx-\bfb}_{M,\bfv'}$
        \State Let $\tilde\bfx \gets \bfx_c + \bar\bfx$
        \State \Return $\tilde\bfx$
	\end{algorithmic}\label{alg:relative-m-active-regression}
\end{algorithm}

\begin{lemma}[Lemma 33 of \cite{ClarksonWoodruff:2015a}]\label{lem:m-norm-net-size}
Let $\bfA\in\mathbb R^{n\times d}$. Let $M:\mathbb R_{\geq0}\to\mathbb R_{\geq0}$ satisfy the conditions of Definition \ref{dfn:m-norm}, and furthermore that $M$ is polynomially bounded below with degree $q_M$ and constant $c_L$ (see Definition \ref{dfn:polynomially-bounded}). Let $\bfw\geq\mathbf{1}_n$ be a set of weights. Consider the subspace $\mathcal V = \Span(\bfA)$. Let $\mathcal C\subset\mathcal V$. Then, there is an $\eps\rho$-covering $\mathcal N$ of $\mathcal B_\rho\cap \mathcal C$ of size at most
\[
    \log\abs*{\mathcal N} \leq O\parens*{d\log\frac1{\eps^{p_M/q_M}}}.
\]
\end{lemma}

\begin{lemma}[Lemma 34 of \cite{ClarksonWoodruff:2015a}]\label{lem:m-norm-net-to-sphere}
Let $\bfA\in\mathbb R^{n\times d}$ and let $\mathcal V = \Span(\bfA)$. Let $\bfb\in\mathbb R^n$. Let $M:\mathbb R_{\geq0}\to\mathbb R_{\geq0}$ satisfy the conditions of Definition \ref{dfn:m-norm}, and furthermore that
\begin{itemize}
    \item $M^{1/p_M}$ is subadditive
    \item $M$ is polynomially bounded below with degree $q_M$ and constant $c_L$ (see Definition \ref{dfn:polynomially-bounded})
\end{itemize}
Let $\bfw, \bfv\geq \mathbf{1}_n$ be two sets of weights. Let $\eps\in(0,1/2)$ and $\rho > 0$. Let $\mathcal N$ be an $\alpha\rho$-cover of $\mathcal B_\rho^{M,\bfw}$ for
\[
    \alpha = \frac{c_L^{1/q_M}}{c_U^{1/p_M}}\eps^{p_M/q_M}.
\]
Then, if
\[
    \abs*{\norm*{\bfy}_{M,\bfv} - \norm*{\bfy}_{M,\bfw}} \leq \eps\rho
\]
for all $\bfy\in(\mathcal N - \bfb)$ and $\bfy\in\mathcal N$, then
\[
    \abs*{\norm*{\bfy}_{M,\bfv} - \norm*{\bfy}_{M,\bfw}} \leq 4\eps\rho
\]
for all $\bfy\in(\mathcal B_\rho^{M,\bfw} - \bfb)$ and $\bfy\in\mathcal B_\rho^{M,\bfw}$. 
\end{lemma}
